/bin/bash -lc "python3 - <<'PY'
import ast, hashlib, json
from pathlib import Path
r=json.loads(Path('runtime_resolved.json').read_text())
p=json.loads(Path('proposal.json').read_text())
try:
 import jsonschema
except ImportError:
 def validate(x,s,path='study'):
  typ=s.get('type')
  ok={'object':lambda:isinstance(x,dict),'array':lambda:isinstance(x,list),'string':lambda:isinstance(x,str)}
  if typ: assert ok[typ](),(path,typ)
  if 'const' in s: assert x==s['const'],path
  if 'enum' in s: assert x in s['enum'],path
  if 'minLength' in s: assert len(x)>=s['minLength'],path
  if 'minItems' in s: assert len(x)>=s['minItems'],path
  if typ=='object':
   assert all(k in x for k in s.get('required',[])),path
   props=s.get('properties',{})
   if s.get('additionalProperties') is False: assert not set(x)-set(props),(path,set(x)-set(props))
   for k,v in x.items():
    if k in props: validate(v,props[k],path+'.'+k)
  if typ=='array':
   for i,v in enumerate(x): validate(v,s.get('items',{}),path+f'[{i}]')
 validate(p['study'],r['study_schema'])
 print('Study validated against runtime schema with recursive standard-library validator.')
else:
 jsonschema.Draft202012Validator(r['study_schema']).validate(p['study'])
 print('Study validated against runtime Draft 2020-12 schema.')
assert set(p)=={'parent_trial','study','variants','knowledge_assessments'}
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert set(p['study']['evidence_refs']) <= set(r['context']['allowed_observation_ids'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert len(p['variants'])==4
assert len({v['name'] for v in p['variants']})==4
assert len({v['file'] for v in p['variants']})==4
assert any(v['role']=='candidate' for v in p['variants'])
normalized=[]
for v in p['variants']:
 assert set(v)=={'name','file','role','config','note'}
 assert v['file']==Path(v['file']).name and v['file'].endswith('.py')
 assert v['role'] in {'candidate','control'}
 src=Path(v['file']).read_text();tree=ast.parse(src)
 compile(tree,v['file'],'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert cfg==v['config']
 assert hashlib.sha256(src.encode()).hexdigest() in v['note']
 normalized.append(src.replace(\"'refresh_query': False\", \"'refresh_query': True\").replace(\"'modulate_keys': False\", \"'modulate_keys': True\").replace('refresh_query=False','refresh_query=True').replace('modulate_keys=False','modulate_keys=True'))
assert len(set(normalized))==1, 'factorial sources differ beyond the two flags'
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()==r['context']['protocol']['source_sha256']['baseline.py']
for a in p['knowledge_assessments']:
 assert a['decision'] in {'used','considered','rejected','unresolved'}
 assert set(a['variant_names']) <= {v['name'] for v in p['variants']}
prior={a['knowledge_id'] for a in r['context']['latest_knowledge_usage']['assessments']}
assert prior <= {a['knowledge_id'] for a in p['knowledge_assessments']}
print('Proposal references/configs/hashes/roles validated; baseline hash preserved.')
print('Factorial source equality verified after normalizing Q/W flags.')
print('No model execution, training, installation or withheld evaluation performed.')
PY"

